package com.college.attendance.controller; import com.college.attendance.dto.*; import com.college.attendance.service.AuthService; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; public AuthController(AuthService a){auth=a;} @PostMapping("/login") public ResponseEntity<?> login(@RequestBody LoginRequest r){try{return ResponseEntity.ok(auth.login(r));}catch(Exception e){return ResponseEntity.status(401).body(java.util.Map.of("message",e.getMessage()));}} }
